import type { ShopProduct, ShopTag } from "./shop";

// More of the live catalogue (14 Oct 2026), read from each shop's own pages:
// GOAT for sneakers, clothing, caps and bags; Watchfinder & Co. for watches.
// Names, colourways, SKUs, sizes and release dates are as the shop lists
// them. Prices are in US dollars as the shop showed them on 14 Oct 2026:
// GOAT's lowest price for a new pair or piece (none when it's sold out), and
// Watchfinder & Co.'s price for that watch. Photos are the shop's own,
// loaded from its image servers. Generated from the harvest; edit by hand
// if a piece sells out or changes.

type Specs = [string, string][];
const GOAT_IMG = "https://image.goat.com/attachments/product_template_additional_pictures/images/";
const GOAT_MAIN = "https://image.goat.com/750/attachments/product_template_pictures/images/";
/** "118984053/1758936_01" → the photo on GOAT's servers ("m:" for the main cut-out) */
const goatPhoto = (key: string) => {
  const main = key.startsWith("m:");
  const [id, file] = (main ? key.slice(2) : key).split("/") as [string, string];
  const dir = `${id.slice(0, 3)}/${id.slice(3, 6)}/${id.slice(6)}`;
  return main ? `${GOAT_MAIN}${dir}/original/${file}.png.png` : `${GOAT_IMG}${dir}/medium/${file}.jpg.jpeg`;
};
/** A Watchfinder & Co. photo by its file name, sized for the shop */
const wfPhoto = (file: string) => `https://www.watchfinder.com/media/catalog/product/${file[0]}/${file[1]}/${file}.jpg?quality=80&bg-color=255,255,255&fit=bounds&height=720&width=576`;

const goat = (id: string, brand: string, name: string, colour: string, category: ShopProduct["category"], kind: string, gender: Gender, price: number | undefined, retail: number | undefined, sizeLabel: string | undefined, sizes: string | undefined, front: string, back: string | undefined, path: string, tags: ShopTag[], released: string | undefined, specs: Specs): ShopProduct => ({
  id, brand, name, colour, category, kind, gender, image: goatPhoto(front), ...(back ? { back: goatPhoto(back) } : {}), stage: "white", credit: "Photo: GOAT",
  photoPage: `https://www.goat.com/${path}`, retailer: "goat", url: `https://www.goat.com/${path}`, tags,
  ...(price ? { price } : {}), ...(retail ? { retail } : {}), ...(sizes ? { sizeLabel: sizeLabel ?? "Size", sizes: sizes.split(" ").map((size) => size.replace(/_/g, " ")) } : {}), ...(released ? { released } : {}), specs,
});
const wfw = (id: string, brand: string, name: string, colour: string, gender: Gender, price: number, note: string, caseSize: string | undefined, front: string, back: string | undefined, path: string, tags: ShopTag[], specs: Specs): ShopProduct => ({
  id, brand, name, colour, category: "Accessories", kind: "Watches", gender, note, price, image: wfPhoto(front), ...(back ? { back: wfPhoto(back) } : {}), stage: "white", credit: "Photo: Watchfinder & Co.",
  photoPage: `https://www.watchfinder.com/watches/${path}`, retailer: "watchfinder", url: `https://www.watchfinder.com/watches/${path}`, tags,
  ...(caseSize ? { sizeLabel: "Case", sizes: [caseSize] } : {}), specs,
});
type Gender = "men" | "women" | "unisex";

